/**
 * Renders the contract error table into the docs site.
 *
 * Reads `ErrorCode` and `errorMessages` from `src/errors/codes.ts` directly, so
 * the page cannot drift from the code. Run by the docs `prebuild` and `predev`
 * scripts. The output is generated; do not edit it by hand.
 */
import { writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { ErrorCode, errorMessages, type ErrorCodeName } from "../src/errors/codes.ts";
import { contractForCode } from "../src/errors/index.ts";

const here = dirname(fileURLToPath(import.meta.url));
const outFile = resolve(here, "../../../apps/docs/src/content/docs/reference/error-codes.md");

const rows = (Object.keys(ErrorCode) as ErrorCodeName[])
  .map((name) => ({ name, code: ErrorCode[name], message: errorMessages[name] }))
  .sort((a, b) => a.code - b.code);

const escapeCell = (text: string) => text.replace(/\|/g, "\\|");

const body = [
  "---",
  "title: Error codes",
  "description: Every contract error code, its name, and the message shown to users.",
  "---",
  "",
  "{/* Generated by packages/sdk/scripts/gen-error-codes.ts. Do not edit by hand. */}",
  "",
  "Contract errors come back as numeric codes. The SDK decodes them into a `ContractError` with the name and message below. The codes are part of the contract ABI: released codes are never renumbered or removed.",
  "",
  "| Code | Contract | Name | Message |",
  "| ---: | --- | --- | --- |",
  ...rows.map(
    (r) =>
      `| ${r.code} | \`${contractForCode(r.code)}\` | \`${r.name}\` | ${escapeCell(r.message)} |`,
  ),
  "",
].join("\n");

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, body);
console.log(`Wrote ${rows.length} error codes to ${outFile}`);
